from pathlib import Path
p=Path('artifacts/three-years/create-post.py')
s=p.read_text(encoding='utf-8-sig')
s=s.replace("title,43,", "title,58,").replace("sub,23,", "sub,28,")
s=s.replace("[(340,fmt(km)","[(350,fmt(km)").replace("(550,fmt(t", "(600,fmt(t").replace("(760,str(count)","(850,str(count)")
s=s.replace("(485,y),value,100", "(515,y),value,136").replace("(545,y+10),label,33", "(560,y+10),label,43")
s=s.replace("(240,290,840,890)","(210,280,930,1000)").replace("[GREEN,LIGHT,BLUE],145)","[GREEN,LIGHT,BLUE],170)")
s=s.replace("(540,560),fmt(km),58", "(570,610),fmt(km),76").replace("(540,625),'kilometres',25", "(570,682),'kilometres',34")
s=s.replace("(885,865,'Cars'", "(930,968,'Cars'").replace("(145,410,'Trucks'", "(130,380,'Trucks'").replace("(400,225,'Boats'", "(405,205,'Boats'")
s=s.replace("label,31,col", "label,42,col").replace("(x,y+47),fmt(val)+' km',30", "(x,y+53),fmt(val)+' km',39")
s=s.replace("(55,315,575,835)", "(25,285,615,875)").replace("[c for _,_,c in labels],120)","[c for _,_,c in labels],136)")
s=s.replace("(315,550),fmt(sum(n.values())),60", "(320,550),fmt(sum(n.values())),78").replace("(315,615),'nights',28", "(320,625),'nights',36")
s=s.replace("y=240+i*69", "y=225+i*84").replace("(620*S,(y-8)*S,638*S,(y+10)*S)","(638*S,(y-10)*S,660*S,(y+12)*S)")
s=s.replace("(656,y),label,27", "(680,y),label,34").replace("(1012,y+30),str(n[k])+' nights',23", "(1030,y+37),str(n[k])+' nights',29")
s=s.replace("y=192+i*27.5", "y=170+i*30.5").replace("(276,y),name,23", "(254,y),name,29").replace("end=302+v/218*630", "end=280+v/218*695")
s=s.replace("(302*S,(y-9)*S,end*S,(y+10)*S)","(280*S,(y-11)*S,end*S,(y+12)*S)").replace("str(v),21,GREEN", "str(v),27,GREEN").replace("(540,979),'Plus 16 nights at sea.',18", "(540,1040),'Plus 16 nights at sea.',24")
p.write_text(s,encoding='utf-8')
